# Builds the relocated power-board application and OTA metadata.
param([ValidateSet("Debug","Release")][string]$Configuration="Debug",[string]$ToolchainBin="C:\ST\STM32CubeCLT_1.21.0\GNU-tools-for-STM32\bin",[switch]$Rebuild)
$ErrorActionPreference="Stop";$root=Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path);$buildArgs=@{Configuration=$Configuration};if($Rebuild){$buildArgs.Rebuild=$true};& (Join-Path $root "Script\build.ps1") @buildArgs
$elf=Join-Path $root "$Configuration\F303_boost.elf";if(-not(Test-Path $elf)){$elf=Join-Path $root "$Configuration\orion_F303_boost_v3.elf"};$bin=Join-Path $root "$Configuration\F303_boost_app.bin";$meta=Join-Path $root "$Configuration\F303_boost_app.metadata.bin";$map=(Get-ChildItem (Join-Path $root $Configuration) -Filter *.map|Select-Object -First 1).FullName
if($null-eq(Select-String -Path $map -Pattern '^FLASH\s+0x08004000\s+0x0001b800'|Select-Object -First 1)){throw "Application linker region mismatch"};& (Join-Path $ToolchainBin "arm-none-eabi-objcopy.exe") -O binary $elf $bin;if($LASTEXITCODE){throw "objcopy failed"};& python (Join-Path $root "Script\generate_boot_metadata.py") $bin $meta;if($LASTEXITCODE){throw "metadata failed"}
